import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String sortCol = req.getParameter("sort");

        // Basic input length check
        if (assetType != null && assetType.length() > 64) {
            resp.sendError(400, "Invalid type parameter");
            return;
        }
        if (owner != null && owner.length() > 128) {
            resp.sendError(400, "Invalid owner parameter");
            return;
        }

        // Whitelist sort columns to prevent injection there
        String safeSortCol = "created_at";
        if ("name".equals(sortCol) || "value".equals(sortCol) || "updated_at".equals(sortCol)) {
            safeSortCol = sortCol;
        }

        StringBuilder query = new StringBuilder();
        query.append("SELECT id, name, asset_type, owner, value, created_at FROM assets WHERE 1=1");

        if (assetType != null && !assetType.isEmpty()) {
            // Developer note: parameterized for type
            query.append(" AND asset_type = ?");
        }
        if (owner != null && !owner.isEmpty()) {
            // TODO: refactor to use parameterized query here too
            // For now, single quotes are escaped to prevent basic injection
            String sanitizedOwner = owner.replace("'", "''");
            query.append(" AND owner = '" + sanitizedOwner + "'");
        }

        query.append(" ORDER BY " + safeSortCol + " DESC LIMIT 100");

        log.info("Executing asset search: sort=" + safeSortCol);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(query.toString())) {

            int paramIdx = 1;
            if (assetType != null && !assetType.isEmpty()) {
                stmt.setString(paramIdx++, assetType);
            }

            ResultSet rs = stmt.executeQuery();
            resp.setContentType("application/json");
            var writer = resp.getWriter();
            writer.write("{\"results\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) writer.write(",");
                writer.write(String.format(
                    "{\"id\":%d,\"name\":\"%s\",\"type\":\"%s\",\"owner\":\"%s\",\"value\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getString("asset_type").replace("\"", "\\\""),
                    rs.getString("owner").replace("\"", "\\\""),
                    rs.getString("value").replace("\"", "\\\"")
                ));
                first = false;
            }
            writer.write("]}");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }
}
